mapper.select:
SELECT count(tid) FROM  yh_jz_service_total_person  tp LEFT JOIN  yh_jz_service_person sp ON tp.user_code=sp.user_code LEFT JOIN yh_user_reginfo re on tp.user_code=re.user_code	LEFT JOIN yh_user_enrolinfo enro	ON enro.user_code=re.user_code
LEFT JOIN yh_jz_service_assessment_switch sas
ON sas.id=sp.childnodes
LEFT JOIN yh_jz_service_bodydata_switch sbs
ON sp.childnodes=sbs.id
LEFT JOIN yh_threshold_dic thdic
ON sp.childnodes=thdic.dic_id




        AND sp.service_state=#{state}



        AND sp.returnvisit=#{returnvisit}



        AND	re.`name` LIKE '%#{name}%'



        AND sp.service_type=#{servicecountent}



        AND re.gender = #{healthstate}



        AND sp.insert_time BETWEEN	#{begintime} AND #{endtime}



        AND re.Org_Code like concat('%', #{Orgcode},'%')


        and sbs.id=#{typeson} and  sp.childtag=1


        and sas.id=(#{typeson}-100) and  sp.childtag=2


        and thdic.dic_id=(#{typeson}-200) and  sp.childtag=4


        AND enro.Flag_Dgroup like concat('%','f'+#{groupid}+'_',"%")



        AND re.Org_Code like concat('%', #{chhooeorgcode},'%')



        AND re.mobile =#{userphone}


        and sp.totaltype=#{totaltype}


        and sp.service_subtitle=#{planname}

SELECT (SELECT COUNT(id) FROM  yh_jz_service_total_person  tp LEFT JOIN  yh_jz_service_person sp ON tp.user_code=sp.user_code LEFT JOIN yh_user_reginfo reg ON reg.user_code=sp.user_code WHERE  sp.service_state=0


    AND sp.insert_time BETWEEN	#{begintime} AND #{endtime}


    and sp.totaltype=#{totaltype}



    AND reg.Org_Code like concat('%', #{Orgcode},'%')

) AS allwattingcount,
(SELECT COUNT(id) FROM  yh_jz_service_total_person  tp LEFT JOIN  yh_jz_service_person sp ON tp.user_code=sp.user_code LEFT JOIN yh_user_reginfo reg ON reg.user_code=sp.user_code WHERE  sp.service_state=1



    AND sp.insert_time BETWEEN	#{begintime} AND #{endtime}


    and sp.totaltype=#{totaltype}



    AND reg.Org_Code like concat('%', #{Orgcode},'%')

) AS allbegincount,
(SELECT COUNT(id) FROM  yh_jz_service_total_person  tp LEFT JOIN  yh_jz_service_person sp ON tp.user_code=sp.user_code LEFT JOIN yh_user_reginfo reg ON reg.user_code=sp.user_code WHERE   sp.service_state=2


    AND sp.insert_time BETWEEN	#{begintime} AND #{endtime}


    and sp.totaltype=#{totaltype}



    AND reg.Org_Code like concat('%', #{Orgcode},'%')

) AS allclosecount,
(SELECT COUNT(id) FROM  yh_jz_service_total_person  tp LEFT JOIN  yh_jz_service_person sp ON tp.user_code=sp.user_code LEFT JOIN yh_user_reginfo reg ON reg.user_code=sp.user_code WHERE   sp.service_state=3


    AND sp.insert_time BETWEEN	#{begintime} AND #{endtime}


    and sp.totaltype=#{totaltype}



    AND reg.Org_Code like concat('%', #{Orgcode},'%')

) AS allfinishicount

SELECT tp.tid,re.`name`,re.gender,tp.doctor_code,admin.user_name as doctorname,re.birth_date,sp.id,sp.user_code,sp.end_service_time,sp.phone,sp.age,sp.start_service_time,sp.service_state,sp.service_waiting_time, sp.service_content,sp.service_type,sp.service_record,sp.isrede,sp.returnvisit,sp.longitude,sp.dimension,sp.insert_time,sp.acceptsituation,sp.childnodes,sp.childtag,sp.satisfaction,sp.service_subtitle,setype.service_name,sas.`name` AS cname,sbs.`name` AS cbname,plan.plan_name,thdic.threshold_name, (SELECT COUNT(id) FROM yh_jz_service_total_person tp LEFT JOIN yh_jz_service_person sp ON tp.user_code=sp.user_code WHERE tp.doctor_code=120 AND sp.service_state=0 AND sp.insert_time BETWEEN '2019-03-22 09:39:33' AND '2021-03-22 09:39:33') AS allwattingcount, (SELECT COUNT(id) FROM yh_jz_service_total_person tp LEFT JOIN yh_jz_service_person sp ON tp.user_code=sp.user_code WHERE tp.doctor_code=120 AND sp.service_state=1 AND sp.insert_time BETWEEN '2019-03-22 09:39:33' AND '2021-03-22 09:39:33') AS allbegincount, (SELECT COUNT(id) FROM yh_jz_service_total_person tp LEFT JOIN yh_jz_service_person sp ON tp.user_code=sp.user_code WHERE tp.doctor_code=120 AND sp.service_state=2 AND sp.insert_time BETWEEN '2019-03-22 09:39:33' AND '2021-03-22 09:39:33') AS allclosecount, (SELECT COUNT(id) FROM yh_jz_service_total_person tp LEFT JOIN yh_jz_service_person sp ON tp.user_code=sp.user_code WHERE tp.doctor_code=120 AND sp.service_state=3 AND sp.insert_time BETWEEN '2019-03-22 09:39:33' AND '2021-03-22 09:39:33') AS allfinishicount FROM yh_jz_service_total_person tp LEFT JOIN yh_jz_service_person sp ON tp.user_code=sp.user_code LEFT JOIN yh_user_reginfo re on tp.user_code=re.user_code LEFT JOIN yh_user_enrolinfo enro ON enro.user_code=re.user_code LEFT JOIN yh_jz_service_type setype ON sp.service_type=setype.id LEFT JOIN yh_jz_service_assessment_switch sas ON sas.id=sp.childnodes LEFT JOIN yh_jz_service_bodydata_switch sbs ON sp.childnodes=sbs.id LEFT JOIN yh_jz_service_plan plan ON sp.childnodes=plan.id LEFT JOIN yh_user_admin_info admin ON admin.user_code=tp.`doctor_code` LEFT JOIN yh_threshold_dic thdic ON sp.childnodes=thdic.dic_id
sp.service_state=#{state}
AND sp.service_type=#{servicetype}
AND re.name like concat('%', #{name},'%')
AND re.gender = #{healthstate}
and sbs.id=#{typeson} and sp.childtag=1
and sas.id=(#{typeson}-100) and sp.childtag=2
and thdic.dic_id=(#{typeson}-200) and sp.childtag=4
AND sp.returnvisit = #{returnvisit}
AND sp.insert_time BETWEEN #{begintime} AND #{endtime}
AND re.Org_Code like concat('%', #{Orgcode},'%')
AND re.Org_Code like concat('%', #{chhooeorgcode},'%')
AND re.mobile =#{userphone}
AND enro.Flag_Dgroup like concat('%','f'+#{groupid}+'_',"%")
and sp.totaltype=#{totaltype}
and sp.service_subtitle=#{planname}
ORDER BY sp.insert_time,re.`name` LIMIT #{beginpage},20
